// ========================================
// Workflow A v2.1 - 增强去重过滤器
// 新增：URL标准化 + 同批次去重
// ========================================

const existingRecords = $input.first().json;
const rssArticles = $('Collect RSS Articles').all();

console.log('\n========================================');
console.log('📊 Workflow A v2.1 - 增强去重分析');
console.log('========================================');
console.log('RSS文章数量:', rssArticles.length);
console.log('飞书记录数量:', existingRecords?.data?.items?.length || 0);

// 检查飞书记录
if (!existingRecords || !existingRecords.data || !existingRecords.data.items) {
  console.log('⚠️ 没有飞书记录，返回所有RSS文章');
  return rssArticles;
}

// ========================================
// 🆕 工具函数：URL标准化
// ========================================
function normalizeUrl(url) {
  if (!url) return '';
  try {
    let normalized = url.toLowerCase().trim();
    // 移除协议（http/https）
    normalized = normalized.replace(/^https?:\/\//, '');
    // 移除www.
    normalized = normalized.replace(/^www\./, '');
    // 移除尾部斜杠
    normalized = normalized.replace(/\/$/, '');
    return normalized;
  } catch (e) {
    return url.toLowerCase().trim();
  }
}

// ========================================
// 提取飞书字段的函数
// ========================================
function extractFeishuUrl(urlField) {
  if (!urlField) return '';
  if (typeof urlField === 'string') return urlField;
  if (typeof urlField === 'object' && urlField.link) return urlField.link;
  if (Array.isArray(urlField) && urlField[0]) {
    if (typeof urlField[0] === 'object' && urlField[0].link) return urlField[0].link;
  }
  return '';
}

function extractFeishuField(field, defaultValue = '') {
  if (!field) return defaultValue;
  if (typeof field === 'string') return field;
  if (Array.isArray(field)) {
    if (field.length === 0) return defaultValue;
    if (field[0] && typeof field[0] === 'object' && field[0].text) {
      return field.map(item => item.text).join(', ');
    }
    return field.join(', ');
  }
  if (typeof field === 'object') {
    if (field.text) return field.text;
  }
  return String(field);
}

// ========================================
// 🆕 建立双重URL索引（精确 + 标准化）
// ========================================
const existingUrls = new Set();           // URL精确匹配
const existingNormalizedUrls = new Set(); // 🆕 URL标准化匹配
const existingTitles = new Set();         // 标题精确匹配

existingRecords.data.items.forEach(record => {
  const url = extractFeishuUrl(record.fields.url);
  if (url) {
    const urlLower = url.toLowerCase().trim();
    existingUrls.add(urlLower);

    // 🆕 添加标准化URL
    const normalizedUrl = normalizeUrl(url);
    if (normalizedUrl) {
      existingNormalizedUrls.add(normalizedUrl);
    }
  }

  const title = extractFeishuField(record.fields.title, '');
  if (title) {
    existingTitles.add(title.toLowerCase().trim());
  }
});

console.log('\n🔍 索引统计：');
console.log('- 精确URL索引:', existingUrls.size);
console.log('- 标准化URL索引:', existingNormalizedUrls.size, '🆕');
console.log('- 标题索引:', existingTitles.size);

// ========================================
// 🆕 同批次去重索引（防止当次收集的重复）
// ========================================
const currentBatchUrls = new Set();
const currentBatchNormalizedUrls = new Set();
const currentBatchTitles = new Set();

// ========================================
// 执行去重
// ========================================
const outputItems = [];
let duplicateCount = 0;
let urlExactDuplicates = 0;
let urlNormalizedDuplicates = 0;
let titleDuplicates = 0;
let batchDuplicates = 0;

for (const article of rssArticles) {
  if (!article || !article.json || !article.json.link) {
    console.log('⚠️ 跳过无效文章');
    continue;
  }

  const articleUrl = article.json.link.toLowerCase().trim();
  const normalizedArticleUrl = normalizeUrl(article.json.link);
  const articleTitle = article.json.title ? article.json.title.toLowerCase().trim() : '';

  let isDuplicate = false;
  let duplicateReason = '';

  // 检查1: URL精确匹配（与飞书）
  if (existingUrls.has(articleUrl)) {
    isDuplicate = true;
    duplicateReason = 'URL精确重复（飞书）';
    urlExactDuplicates++;
  }

  // 🆕 检查2: URL标准化匹配（与飞书）
  if (!isDuplicate && existingNormalizedUrls.has(normalizedArticleUrl)) {
    isDuplicate = true;
    duplicateReason = 'URL标准化重复（飞书）- http/https或www差异';
    urlNormalizedDuplicates++;
  }

  // 检查3: 标题精确匹配（与飞书）
  if (!isDuplicate && articleTitle && existingTitles.has(articleTitle)) {
    isDuplicate = true;
    duplicateReason = '标题重复（飞书）';
    titleDuplicates++;
  }

  // 🆕 检查4: 同批次URL去重
  if (!isDuplicate && currentBatchUrls.has(articleUrl)) {
    isDuplicate = true;
    duplicateReason = '同批次URL重复';
    batchDuplicates++;
  }

  // 🆕 检查5: 同批次标准化URL去重
  if (!isDuplicate && currentBatchNormalizedUrls.has(normalizedArticleUrl)) {
    isDuplicate = true;
    duplicateReason = '同批次URL标准化重复';
    batchDuplicates++;
  }

  // 🆕 检查6: 同批次标题去重
  if (!isDuplicate && articleTitle && currentBatchTitles.has(articleTitle)) {
    isDuplicate = true;
    duplicateReason = '同批次标题重复';
    batchDuplicates++;
  }

  if (!isDuplicate) {
    outputItems.push({ json: article.json });

    // 🆕 立即添加到当前批次索引
    currentBatchUrls.add(articleUrl);
    currentBatchNormalizedUrls.add(normalizedArticleUrl);
    if (articleTitle) {
      currentBatchTitles.add(articleTitle);
    }

    console.log(`✅ 新文章: ${article.json.title}`);
  } else {
    duplicateCount++;
    console.log(`❌ 重复: ${article.json.title}`);
    console.log(`   原因: ${duplicateReason}`);
  }
}

// ========================================
// 统计报告
// ========================================
console.log('\n========================================');
console.log('📊 去重统计（v2.1增强版）');
console.log('========================================');
console.log('RSS文章总数:', rssArticles.length);
console.log('\n与飞书重复：');
console.log('  - URL精确重复:', urlExactDuplicates);
console.log('  - URL标准化重复:', urlNormalizedDuplicates, '🆕');
console.log('  - 标题重复:', titleDuplicates);
console.log('\n同批次重复:', batchDuplicates, '🆕');
console.log('\n总重复数量:', duplicateCount);
console.log('新文章数量:', outputItems.length);
console.log('去重率:', ((duplicateCount / rssArticles.length) * 100).toFixed(1) + '%');
console.log('========================================\n');

if (outputItems.length === 0) {
  console.log('✅ 没有新文章需要处理，停止工作流');
  return [];
}

// 补全缺失字段
const cleanedItems = outputItems.map(item => {
  const article = item.json;

  const description = article.description
    || article.content
    || article.summary
    || article.contentSnippet
    || article['content:encoded']
    || article.body
    || '';

  const creator = article.creator
    || article.author
    || article['dc:creator']
    || article.publisher
    || '';

  const rssSourceUrl = article.rssSourceUrl
    || article.feedUrl
    || article.meta?.link
    || article.sourceUrl
    || '';

  return {
    json: {
      ...article,
      description: description,
      creator: creator,
      rssSourceUrl: rssSourceUrl
    }
  };
});

console.log(`✅ 返回 ${cleanedItems.length} 篇新文章继续处理`);
return cleanedItems;

// 获取配置和token
const config = $('Configuration').item.json;
const tokenData = $('Get Feishu Token').item.json;
const token = tokenData.tenant_access_token;

if (!token) {
  throw new Error('无法获取飞书访问令牌');
}

// 收集所有RSS数据
const allArticles = [];
const inputs = $input.all();

console.log('=== RSS收集调试信息 ===');
console.log('输入节点数量:', inputs.length);

// 根据RSS源URL确定来源的映射
const rssSourceMapping = {
  'https://plink.anyfeeder.com/weixin/AI_era': '新智元',
  'https://rsshub.app/aibase/news': 'AIBase',
  'https://plink.anyfeeder.com/weixin/qqtech': '腾讯科技',
  'https://www.qbitai.com/feed': '量子位',
  'https://36kr.com/feed': '36氪',
  'https://www.jiqizhixin.com/rss': '机器之心',
  'http://www.geekpark.net/rss': '极客公园'
};

// 处理RSS Feed Read节点的数据
for (let i = 0; i < inputs.length; i++) {
  console.log(`处理RSS节点 ${i}...`);

  if (inputs[i].json) {
    let sourceName = '未知来源';

    // 方法1：从RSS源URL中确定来源
    const rssSourceUrl = inputs[i].json?.rssSourceUrl || inputs[i].json?.sourceUrl || '';
    console.log(`RSS节点 ${i} rssSourceUrl: ${rssSourceUrl}`);

    for (const [urlPattern, source] of Object.entries(rssSourceMapping)) {
      if (rssSourceUrl.includes(urlPattern) || rssSourceUrl === urlPattern) {
        sourceName = source;
        console.log(`通过rssSourceUrl匹配到来源: ${source} (模式: ${urlPattern})`);
        break;
      }
    }

    // 方法2：从文章链接中确定来源
    if (sourceName === '未知来源') {
      const articleUrl = inputs[i].json?.link || inputs[i].json?.url || '';
      console.log(`RSS节点 ${i} 文章链接: ${articleUrl}`);

      if (articleUrl.includes('weixin.sogou.com') && articleUrl.includes('AI_era')) sourceName = '新智元';
      else if (articleUrl.includes('aibase.com')) sourceName = 'AIBase';
      else if (articleUrl.includes('weixin.sogou.com') && articleUrl.includes('qqtech')) sourceName = '腾讯科技';
      else if (articleUrl.includes('qbitai.com')) sourceName = '量子位';
      else if (articleUrl.includes('36kr.com')) sourceName = '36氪';
      else if (articleUrl.includes('jiqizhixin.com')) sourceName = '机器之心';
      else if (articleUrl.includes('geekpark.net')) sourceName = '极客公园';

      if (sourceName !== '未知来源') {
        console.log(`通过文章链接匹配到来源: ${sourceName}`);
      }
    }

    // 方法3：从feedTitle中确定来源
    if (sourceName === '未知来源') {
      const feedTitle = inputs[i].json?.feedTitle || inputs[i].json?.title || '';
      console.log(`RSS节点 ${i} feedTitle: ${feedTitle}`);

      if (feedTitle.includes('AI_era') || feedTitle.includes('新智元')) sourceName = '新智元';
      else if (feedTitle.includes('aibase') || feedTitle.includes('AIBase')) sourceName = 'AIBase';
      else if (feedTitle.includes('qqtech') || feedTitle.includes('腾讯科技')) sourceName = '腾讯科技';
      else if (feedTitle.includes('qbitai') || feedTitle.includes('量子位')) sourceName = '量子位';
      else if (feedTitle.includes('36kr') || feedTitle.includes('36氪')) sourceName = '36氪';
      else if (feedTitle.includes('jiqizhixin') || feedTitle.includes('机器之心')) sourceName = '机器之心';
      else if (feedTitle.includes('geekpark') || feedTitle.includes('极客公园')) sourceName = '极客公园';

      if (sourceName !== '未知来源') {
        console.log(`通过feedTitle匹配到来源: ${sourceName}`);
      }
    }

    // 方法4：从creator字段中确定来源（作为备用）
    if (sourceName === '未知来源') {
      const creator = inputs[i].json?.creator || '';
      console.log(`RSS节点 ${i} creator: ${creator}`);

      if (creator.includes('AI base') || creator.includes('AIBase')) sourceName = 'AIBase';
      else if (creator.includes('明敏')) sourceName = '量子位';

      if (sourceName !== '未知来源') {
        console.log(`通过creator匹配到来源: ${sourceName}`);
      }
    }

    // 方法5：根据输入顺序确定来源（最后备用）
    if (sourceName === '未知来源') {
      const predefinedSources = ['新智元', 'AIBase', '腾讯科技', '量子位', '量子位', '36氪', '机器之心', '极客公园'];
      const sourceIndex = i;
      if (sourceIndex >= 0 && sourceIndex < predefinedSources.length) {
        sourceName = predefinedSources[sourceIndex];
        console.log(`通过输入顺序匹配到来源: ${sourceName} (索引: ${sourceIndex})`);
      }
    }

    console.log(`RSS节点 ${i} 最终来源: ${sourceName}`);

    // RSS Feed Read节点会直接返回解析好的数据
    const article = inputs[i].json;

    // 处理时间格式
    let pubDate = article.pubDate || article.published || new Date().toISOString();

    // 如果是Unix时间戳（数字），转换为ISO字符串
    if (typeof pubDate === 'number') {
      pubDate = new Date(pubDate * 1000).toISOString();
    } else if (typeof pubDate === 'string') {
      // 尝试解析各种日期格式
      const date = new Date(pubDate);
      if (!isNaN(date.getTime())) {
        pubDate = date.toISOString();
      } else {
        pubDate = new Date().toISOString();
      }
    }

    const newArticle = {
      title: article.title || article.name || '',
      description: article.description || article.content || article.summary || '',
      link: article.link || article.url || '',
      pubDate: pubDate,
      source: sourceName,
      guid: article.guid || article.id || '',
      feedTitle: article.feedTitle || sourceName,
      creator: article.creator || '',
      rssSourceUrl: article.rssSourceUrl || ''
    };

    allArticles.push(newArticle);
  }
}

// 简单去重（基于标题和链接）
const uniqueArticles = [];
const seenTitles = new Set();
const seenLinks = new Set();

allArticles.forEach(article => {
  const titleKey = article.title.toLowerCase().trim();
  const linkKey = article.link.toLowerCase().trim();

  if (!seenTitles.has(titleKey) && !seenLinks.has(linkKey)) {
    seenTitles.add(titleKey);
    seenLinks.add(linkKey);
    uniqueArticles.push(article);
  } else {
    console.log('跳过重复RSS文章:', article.title);
  }
});

console.log(`收集到 ${uniqueArticles.length} 篇RSS文章（去重后）`);

// 为每篇文章添加配置信息
return uniqueArticles.map(article => ({
  ...article,
  _token: token,
  _config: config,
  created_at: new Date().toISOString(),
  status: '待筛选',
  article_type: 'rss'
}));

// 在 Catch Error 节点的 JavaScript 代码中
const error = $input.first().json;

console.log('Query Existing Records 节点出错:', error);

// 检查是否是频率限制错误
if (error.errorMessage && error.errorMessage.includes('request trigger frequency limit')) {
  console.log('检测到API频率限制，等待重试...');

  // 等待一段时间后重试
  await new Promise(resolve => setTimeout(resolve, 10000)); // 等待10秒

  // 可以在这里添加重试逻辑或发送通知
  return [{
    json: {
      error_type: 'rate_limit',
      message: 'API频率限制，已等待重试',
      retry_after: 10
    }
  }];
}

// 其他错误处理
return [{
  json: {
    error_type: 'other',
    message: error.errorMessage || '未知错误',
    original_error: error
  }
}];

// ========================================
// Clean and Parse Output - v2.1.1 完全修复版
// 消除所有TypeScript警告
// ========================================

try {
  // 获取当前item的数据
  const currentItem = $input.item.json;
  let aiOutput = currentItem.output || currentItem.text || currentItem;

  console.log('=== AI 输出处理 (Item', $itemIndex + 1, ') ===');
  console.log('输入类型:', typeof aiOutput);

  // 获取原始RSS数据作为备用
  const originalTitle = currentItem.title || $input.item.json.title || '未知标题';
  const originalSource = currentItem.source || $input.item.json.source || '未知来源';
  const originalLink = currentItem.link || $input.item.json.link || '';
  const originalDate = currentItem.pubDate || $input.item.json.pubDate || new Date().toISOString();

  // 定义默认值
  const defaultOutput = {
    '标题': originalTitle,
    '日期': originalDate,
    '内容': '内容解析失败,请查看原始数据',
    '媒体': originalSource,
    '链接': originalLink,
    '相关度评分': 50,
    '关键词': ['AI'],
    '分类': ['行业动态']
  };

  // 如果是字符串,尝试清理和解析
  if (typeof aiOutput === 'string') {
    console.log('检测到字符串格式,开始清理...');

    try {
      // 1. 移除 Markdown 代码块标记
      aiOutput = aiOutput
        .replace(/```json\s*/gi, '')
        .replace(/```\s*/g, '')
        .trim();

      // 2. 尝试提取 JSON 对象(从第一个 { 到最后一个 })
      const jsonMatch = aiOutput.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        aiOutput = jsonMatch[0];
        console.log('✅ 成功提取 JSON 对象');
      } else {
        console.log('⚠️ 未找到 JSON 对象,使用默认值');
        aiOutput = defaultOutput;
      }

      // 3. 如果仍是字符串,尝试解析
      if (typeof aiOutput === 'string') {
        aiOutput = JSON.parse(aiOutput);
        console.log('✅ JSON 解析成功');
      }
    } catch (e) {
      // ✅ 修复：安全的错误处理
      const errorMsg = e instanceof Error ? e.message : String(e);
      const errorContent = typeof aiOutput === 'string' ? aiOutput.substring(0, 300) : JSON.stringify(aiOutput).substring(0, 300);

      console.log('❌ 解析过程出错:', errorMsg);
      console.log('失败内容:', errorContent);
      console.log('使用默认值继续处理');
      aiOutput = defaultOutput;
    }
  }

  // 如果不是对象,使用默认值
  if (typeof aiOutput !== 'object' || aiOutput === null) {
    console.log('⚠️ 输出不是有效对象,使用默认值');
    aiOutput = defaultOutput;
  }

  // 验证和补全所有必需字段
  const finalOutput = {
    '标题': aiOutput['标题'] || defaultOutput['标题'],
    '日期': aiOutput['日期'] || defaultOutput['日期'],
    '内容': aiOutput['内容'] || defaultOutput['内容'],
    '媒体': aiOutput['媒体'] || defaultOutput['媒体'],
    '链接': aiOutput['链接'] || defaultOutput['链接'],
    '相关度评分': (() => {
      try {
        const score = aiOutput['相关度评分'];
        if (typeof score === 'number') return score;
        if (typeof score === 'string') {
          const parsed = parseInt(score);
          return isNaN(parsed) ? defaultOutput['相关度评分'] : parsed;
        }
        return defaultOutput['相关度评分'];
      } catch (e) {
        // ✅ 修复：即使这里出错也返回默认值
        return defaultOutput['相关度评分'];
      }
    })(),
    '关键词': Array.isArray(aiOutput['关键词']) ? aiOutput['关键词'] : defaultOutput['关键词'],
    '分类': Array.isArray(aiOutput['分类']) ? aiOutput['分类'] : defaultOutput['分类']
  };

  console.log('✅ Item', $itemIndex + 1, '处理完成');

  // 返回对象（不是数组）
  return {
    json: {
      output: finalOutput
    }
  };

} catch (error) {
  // ✅ 修复：安全的错误处理
  const errorMsg = error instanceof Error ? error.message : String(error);
  const errorStack = error instanceof Error ? error.stack : '';

  console.log('');
  console.log('❌❌❌ Clean and Parse Output 致命错误 ❌❌❌');
  console.log('Item', $itemIndex + 1, '处理出现异常:', errorMsg);
  if (errorStack) {
    console.log('错误堆栈:', errorStack);
  }

  // 尝试获取原始数据
  let fallbackTitle = '未知标题';
  let fallbackSource = '未知来源';
  let fallbackLink = '';
  let fallbackDate = new Date().toISOString();

  try {
    const currentItem = $input.item.json;
    fallbackTitle = currentItem.title || $input.item.json.title || '未知标题';
    fallbackSource = currentItem.source || $input.item.json.source || '未知来源';
    fallbackLink = currentItem.link || $input.item.json.link || '';
    fallbackDate = currentItem.pubDate || $input.item.json.pubDate || new Date().toISOString();
  } catch (e) {
    // ✅ 修复：安全的错误处理
    const msg = e instanceof Error ? e.message : String(e);
    console.log('无法获取原始数据:', msg);
  }

  // 返回带错误标记的默认item
  console.log('⚠️ 返回默认值item以继续工作流');

  return {
    json: {
      output: {
        '标题': fallbackTitle + ' [解析失败]',
        '日期': fallbackDate,
        '内容': '此文章在AI分析后的解析阶段出现错误，请手动检查。错误信息: ' + errorMsg,
        '媒体': fallbackSource,
        '链接': fallbackLink,
        '相关度评分': 0,
        '关键词': ['解析错误'],
        '分类': ['待处理']
      },
      _error: true,
      _error_message: errorMsg,
      _item_index: $itemIndex
    }
  };
}
